return ['domain'=>'slashphoto','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'sv_SE','project-id-version'=>'SlashPhoto 0.1.0-dev','pot-creation-date'=>'2026-11-22T15:11:14+00:00','po-revision-date'=>'2026-11-22 16:10+0100','messages'=>['SlashPhoto'=>'SlashPhoto','Open-source photography galleries, client proofing and photo sales for WordPress. No subscriptions, no locked features.'=>'Fotogallerier, bildurval för kunder och bildförsäljning med öppen källkod för WordPress. Inga prenumerationer, inga låsta funktioner.','Slashmad'=>'Slashmad','Invalid post ID.'=>'Ogiltigt inläggs-ID.','The form has expired. Please go back, reload the page and try again.'=>'Formuläret har gått ut. Gå tillbaka, ladda om sidan och försök igen.','Secret link for galleries in share-link mode.'=>'Hemlig länk för gallerier som delas med länk.','[%s] Your sign-in link'=>'[%s] Din inloggningslänk','Use this link to sign in and open %s. It works once, for one hour.'=>'Använd den här länken för att logga in och öppna %s. Den fungerar en gång, i en timme.','If you did not ask for it, you can ignore this email.'=>'Om du inte har bett om den kan du bortse från det här mejlet.','Access'=>'Åtkomst','Who can view this gallery'=>'Vem kan se galleriet','Everyone with the link'=>'Alla som har länken','Only people with the secret link'=>'Bara de som har den hemliga länken','Anyone logged in to this site'=>'Alla som är inloggade på webbplatsen','Only selected clients (log-in required)'=>'Bara utvalda kunder (inloggning krävs)','Secret link'=>'Hemlig länk','Create a new link (the current one stops working)'=>'Skapa en ny länk (den nuvarande slutar fungera)','Ask for an email address'=>'Be om e-postadress','No, or as the parent gallery'=>'Nej, eller som i överordnat galleri','Yes'=>'Ja','No, not for this gallery'=>'Nej, inte för det här galleriet','Watermark'=>'Vattenstämpel','Site default or parent gallery'=>'Webbplatsens standard eller överordnat galleri','On'=>'På','Off'=>'Av','Client selections (proofing)'=>'Kundernas bildurval','Same as parent gallery (off at the top level)'=>'Som i överordnat galleri (av på översta nivån)','Maximum images per selection (0 = no limit)'=>'Högsta antal bilder per urval (0 = ingen gräns)','Not for sale'=>'Inte till salu','Current price list unavailable'=>'Den valda prislistan finns inte längre','Price list'=>'Prislista','Clients (user names or emails, comma separated)'=>'Kunder (användarnamn eller e-postadresser, kommaseparerade)','Available until'=>'Tillgängligt till och med','Terms to accept before viewing'=>'Villkor att godkänna innan galleriet visas','Use Edit page content to manage the gallery password. Sub-galleries also follow the access rules of their parent galleries.'=>'Använd Redigera sidans innehåll för att ändra galleriets lösenord. Undergallerier följer också åtkomstreglerna för galleriet ovanför.','Set a password under Visibility. Sub-galleries also follow the rules of the galleries above them.'=>'Ange ett lösenord under Synlighet. Undergallerier följer också reglerna för gallerierna ovanför.','No views counted in this period.'=>'Inga visningar räknades under perioden.','Daily totals'=>'Dagliga totaler','Date'=>'Datum','Views'=>'Visningar','Donations'=>'Donationer','SlashPhoto is free to use. If you would like to support its development, choose a donation service.'=>'SlashPhoto är gratis att använda. Om du vill stödja utvecklingen kan du välja en donationstjänst.','WordPress accepted the invitation for sending.'=>'WordPress tog emot inbjudan för att skicka den.','WordPress could not send this invitation. Check the site’s email settings and try again.'=>'WordPress kunde inte skicka inbjudan. Kontrollera webbplatsens e-postinställningar och försök igen.','Publish the gallery and its parent galleries and check their expiry dates before sending an invitation.'=>'Publicera galleriet och gallerierna ovanför och kontrollera deras slutdatum innan du skickar en inbjudan.','Enter a valid email address.'=>'Ange en giltig e-postadress.','This address needs a WordPress account that matches the gallery’s access settings.'=>'Adressen behöver ett WordPress-konto som stämmer med galleriets åtkomstinställningar.','An editor of the parent gallery must send invitations that use its secret link.'=>'Inbjudningar som använder det överordnade galleriets hemliga länk måste skickas av någon som får redigera det galleriet.','This gallery requires multiple secret links. Share the links individually from each gallery’s settings.'=>'Galleriet kräver flera hemliga länkar. Dela länkarna en i taget från respektive galleris inställningar.','Open the gallery’s access settings to create a secret link before sending an invitation.'=>'Öppna galleriets åtkomstinställningar och skapa en hemlig länk innan du skickar en inbjudan.','Invite a client'=>'Bjud in en kund','Anyone with the secret link can use it. A parent gallery’s link can also open that gallery and other galleries that inherit its link.'=>'Alla som har den hemliga länken kan använda den. Ett överordnat galleris länk kan också öppna det galleriet och andra gallerier som ärver dess länk.','Share the gallery password separately.'=>'Dela galleriets lösenord separat.','Client email'=>'Kundens e-postadress','Message (optional)'=>'Meddelande (valfritt)','Send invitation'=>'Skicka inbjudan','You cannot invite clients to this gallery.'=>'Du kan inte bjuda in kunder till det här galleriet.','Gallery invitation: %s'=>'Inbjudan till galleri: %s','You are invited to view %s.'=>'Du är inbjuden att se %s.','Sign in without a password with this link. It works once, within seven days:'=>'Logga in utan lösenord med den här länken. Den fungerar en gång, inom sju dagar:','Sign in with the WordPress account registered to this email address.'=>'Logga in med WordPress-kontot som hör till den här e-postadressen.','Use the gallery password shared with you separately.'=>'Använd galleriets lösenord som du har fått separat.','Public'=>'Offentligt','Private / unpublished'=>'Privat / opublicerat','Password protected'=>'Lösenordsskyddat','Restricted'=>'Begränsat','Overview'=>'Översikt','Visibility'=>'Synlighet','Selections'=>'Urval','No selections'=>'Inga urval','%d sent'=>'%d skickat' . "\0" . '%d skickade','%d choosing'=>'%d väljer' . "\0" . '%d väljer','Galleries'=>'Gallerier','All galleries'=>'Alla gallerier','List view'=>'Listvy','Add new gallery'=>'Lägg till nytt galleri','(Untitled gallery)'=>'(Galleri utan namn)','View list'=>'Visa lista','No galleries in this group yet.'=>'Inga gallerier i den här gruppen ännu.','Gallery workspace'=>'Galleriets arbetsyta','You cannot edit this gallery.'=>'Du kan inte redigera det här galleriet.','Photos'=>'Bilder','Settings'=>'Inställningar','Client selections'=>'Kundernas urval','Invite'=>'Bjud in','← All galleries'=>'← Alla gallerier','Edit page content'=>'Redigera sidans innehåll','View gallery'=>'Visa galleriet','Publish gallery'=>'Publicera galleriet','Gallery settings saved.'=>'Galleriets inställningar har sparats.','Gallery sections'=>'Galleriets avsnitt','View selections across galleries'=>'Visa urval i alla gallerier','Upload photos'=>'Ladda upp bilder','Reorder photos'=>'Ändra ordning på bilderna','Done'=>'Klar','Make new copies'=>'Gör nya kopior','Make new copies remakes the web copies of every photo in this gallery from the originals, with the current watermark, display size and image-processing settings. The originals are not changed.'=>'Gör nya kopior skapar om webbkopiorna av alla bilder i galleriet från originalen, med nuvarande vattenstämpel, visningsstorlek och bildbehandling. Originalen ändras inte.','Photo order saved.'=>'Bildordningen har sparats.','The photo order could not be saved. Review the current order and try again.'=>'Bildordningen kunde inte sparas. Kontrollera den nuvarande ordningen och försök igen.','Choose a photo in this gallery and a position within the photo count.'=>'Välj en bild i galleriet och en position inom antalet bilder.','Enter a position and select Move. Position 1 is the first photo visitors see.'=>'Ange en position och välj Flytta. Position 1 är den första bilden besökarna ser.','This gallery has no photos yet.'=>'Galleriet har inga bilder ännu.','(Untitled photo)'=>'(Bild utan namn)','Position for %s'=>'Position för %s','Move %s'=>'Flytta %s','Move'=>'Flytta','Gallery name'=>'Galleriets namn','Access and proofing'=>'Åtkomst och bildurval','Shop'=>'Butik','Start with a draft. You can upload photos and choose who can see the gallery before publishing.'=>'Börja med ett utkast. Du kan ladda upp bilder och välja vem som ser galleriet innan du publicerar.','Create draft and add photos'=>'Skapa utkast och lägg till bilder','You cannot make this change to the gallery.'=>'Du kan inte göra den här ändringen i galleriet.','Enter a name for the gallery.'=>'Ange ett namn på galleriet.','Gift cards'=>'Presentkort','You cannot manage gift cards.'=>'Du kan inte hantera presentkort.','The gift card can no longer be used.'=>'Presentkortet kan inte längre användas.','The gift card can be used again.'=>'Presentkortet kan användas igen.','Enter an amount above zero.'=>'Ange ett belopp större än noll.','That did not work. Reload the page and try again.'=>'Det fungerade inte. Ladda om sidan och försök igen.','Gift card created. Copy the code now: it is not stored and cannot be shown again.'=>'Presentkortet har skapats. Kopiera koden nu: den sparas inte och kan inte visas igen.','New gift card code'=>'Ny presentkortskod','Gift cards are for sale on pages with the [slashphoto_gift_cards] shortcode.'=>'Presentkort säljs på sidor med kortkoden [slashphoto_gift_cards].','Gift cards are not for sale. Switch them on under Shop settings → Gift cards; cards made here can be used either way.'=>'Presentkort säljs inte. Slå på dem under Butiksinställningar → Presentkort; kort som skapas här kan användas i vilket fall som helst.','Create a gift card'=>'Skapa ett presentkort','Amount (%s)'=>'Belopp (%s)','Create'=>'Skapa','For prizes, apologies or cards you sell yourself. The validity in the shop settings applies.'=>'För priser, ursäkter eller kort som du själv säljer. Giltighetstiden i butiksinställningarna gäller.','All gift cards'=>'Alla presentkort','No gift cards yet.'=>'Inga presentkort ännu.','Code ends with'=>'Koden slutar på','Amount'=>'Belopp','Left'=>'Kvar','Source'=>'Källa','Valid until'=>'Giltigt till','Status'=>'Status','returned'=>'återfört','Order %d'=>'Order %d','Made by hand'=>'Skapat för hand','No end date'=>'Inget slutdatum','Void'=>'Spärrat','Expired'=>'Utgånget','Active'=>'Aktivt','Used up'=>'Förbrukat','Reactivate'=>'Aktivera igen','Import from Sunshine'=>'Importera från Sunshine','Import from Sunshine Photo Cart'=>'Importera från Sunshine Photo Cart','Copies your Sunshine galleries, images, prices and orders into SlashPhoto. Sunshine’s own data is only read and never changed, so you can compare both before you switch Sunshine off. You can run the import again: what is already imported is skipped.'=>'Kopierar dina gallerier, bilder, priser och ordrar från Sunshine till SlashPhoto. Sunshines egna data läses bara och ändras aldrig, så du kan jämföra båda innan du stänger av Sunshine. Du kan köra importen igen: det som redan är importerat hoppas över.','Sunshine data in the WordPress database'=>'Sunshine-data i WordPress-databasen','Sunshine Photo Cart is inactive. These records were left in the WordPress database and can still be imported.'=>'Sunshine Photo Cart är inaktivt. De här posterna finns kvar i WordPress-databasen och kan fortfarande importeras.','%d gallery'=>'%d galleri' . "\0" . '%d gallerier','%d image'=>'%d bild' . "\0" . '%d bilder','%d product'=>'%d produkt' . "\0" . '%d produkter','%d price level'=>'%d prisnivå' . "\0" . '%d prisnivåer','%d order'=>'%d order' . "\0" . '%d ordrar','How things are carried over'=>'Så förs uppgifterna över','Each price level becomes a price list with the products that have a price at that level; galleries keep their price level. Downloads stay downloads, everything else becomes a print.'=>'Varje prisnivå blir en prislista med produkterna som har ett pris på den nivån; gallerierna behåller sin prisnivå. Nedladdningar förblir nedladdningar, allt annat blir prints.','Galleries keep their title, text, order, sub-galleries, password, private clients, expiry date and terms. Galleries opened with a direct URL get a secret link; “Provide email address” becomes an email request and “Registered and logged in” the logged-in mode. Email addresses visitors gave and terms agreements Sunshine recorded go to SlashPhoto → Visitors.'=>'Gallerierna behåller titel, text, ordning, undergallerier, lösenord, privata kunder, slutdatum och villkor. Gallerier som öppnades med en direktadress får en hemlig länk; ”Ange e-postadress” blir en e-postförfrågan och ”Registrerad och inloggad” blir läget för inloggade. E-postadresser som besökare har lämnat och villkorsgodkännanden som Sunshine har sparat hamnar under SlashPhoto → Besökare.','Images are copied: each gets a display copy and its original is stored privately, exactly like new uploads. This needs disk space for a second copy until you remove Sunshine.'=>'Bilderna kopieras: var och en får en visningskopia och originalet sparas privat, precis som vid nya uppladdningar. Det kräver diskutrymme för en andra kopia tills du tar bort Sunshine.','Orders are copied with their lines and amounts for your records. Customers do not get emails, and their old Sunshine order links do not carry over.'=>'Ordrarna kopieras med rader och belopp för din bokföring. Kunderna får inga mejl, och deras gamla orderlänkar från Sunshine följer inte med.','Look for new Sunshine content again'=>'Sök efter nytt innehåll i Sunshine igen','Start the import'=>'Starta importen','Continue the import'=>'Fortsätt importen','The import is complete.'=>'Importen är klar.','The last import run copied no records.'=>'Den senaste importkörningen kopierade inga poster.','Imported so far: %1$d price lists, %2$d galleries, %3$d images, %4$d orders, %5$d visitor log entries.'=>'Importerat hittills: %1$d prislistor, %2$d gallerier, %3$d bilder, %4$d ordrar, %5$d poster i besöksloggen.','To check'=>'Att kontrollera','Copying price lists…'=>'Kopierar prislistor…','Creating galleries…'=>'Skapar gallerier…','Copying images… This can take a while; keep this page open.'=>'Kopierar bilder… Det kan ta en stund; låt sidan vara öppen.','Copying orders…'=>'Kopierar ordrar…','The import stopped because of an error. Click the button to continue.'=>'Importen stoppades av ett fel. Klicka på knappen för att fortsätta.','Orders'=>'Ordrar','You are not allowed to change orders.'=>'Du har inte behörighet att ändra ordrar.','Order not found.'=>'Ordern hittades inte.','Export paid prints CSV'=>'Exportera betalda prints som CSV','No orders in this status.'=>'Inga ordrar med den här statusen.','Export prints CSV'=>'Exportera prints som CSV','Search orders'=>'Sök ordrar','All orders'=>'Alla ordrar','Receipt'=>'Kvitto','Invoice'=>'Faktura','Order summary'=>'Ordersammanfattning','Order updated.'=>'Ordern har uppdaterats.','Image'=>'Bild','Product'=>'Produkt','Quantity'=>'Antal','Total'=>'Totalt','Original'=>'Original','Delivered at %d px on the longest side'=>'Levereras med %d px på längsta sidan','Delivered as the full-size original'=>'Levereras som originalet i full storlek','In package'=>'I paket','Download'=>'Ladda ner','Deleted'=>'Raderad','Discount (%s)'=>'Rabatt (%s)','Discount'=>'Rabatt','Shipping'=>'Frakt','Including VAT'=>'Varav moms','VAT'=>'Moms','Gift card (…%s)'=>'Presentkort (…%s)','To pay'=>'Att betala','Message from the customer'=>'Meddelande från kunden','Customer'=>'Kund','Delivery address'=>'Leveransadress','Placed %1$s · %2$s'=>'Lagd %1$s · %2$s','Paid %s'=>'Betald %s','The customer gets an email when the order becomes paid, completed, cancelled or refunded. Marking it paid opens the downloads. Refunds through Stripe are made in the Stripe Dashboard.'=>'Kunden får ett mejl när ordern blir betald, klar, avbruten eller återbetald. När du markerar den som betald öppnas nedladdningarna. Återbetalningar via Stripe görs i Stripes instrumentpanel.','Private note'=>'Privat anteckning','Update order'=>'Uppdatera ordern','Order'=>'Order','All'=>'Alla','No orders yet.'=>'Inga ordrar ännu.','You cannot export print orders.'=>'Du kan inte exportera printordrar.','The export could not be opened.'=>'Exporten kunde inte öppnas.','All selections in this gallery'=>'Alla urval i det här galleriet','This selection could not be found in the gallery.'=>'Urvalet kunde inte hittas i galleriet.','No client has chosen any images yet. Clients choose favourites while logged in and send them to you from the gallery page.'=>'Ingen kund har valt några bilder ännu. Kunderna väljer favoriter när de är inloggade och skickar dem till dig från gallerisidan.','Deleted user'=>'Raderad användare','%s photo'=>'%s bild' . "\0" . '%s bilder','File names for Lightroom'=>'Filnamn för Lightroom','Selected photo file names'=>'Filnamn för valda bilder','Download CSV'=>'Ladda ner CSV','Let the client change it'=>'Låt kunden ändra det','Delete this selection? This cannot be undone.'=>'Radera urvalet? Det går inte att ångra.','Delete selection'=>'Radera urvalet','Submitted'=>'Skickat','Still choosing'=>'Väljer fortfarande','You are not allowed to manage this selection.'=>'Du har inte behörighet att hantera det här urvalet.','Unknown selection action.'=>'Okänd åtgärd för urval.','Selection status'=>'Urvalets status','Gallery'=>'Galleri','Filter'=>'Filtrera','%s selection'=>'%s urval' . "\0" . '%s urval','Selection pages'=>'Sidor med urval','No client selections match these filters.'=>'Inga kundurval matchar filtren.','Review selection'=>'Granska urvalet','SlashPhoto settings'=>'Inställningar för SlashPhoto','Centre'=>'Mitten','Top left'=>'Uppe till vänster','Top right'=>'Uppe till höger','Bottom left'=>'Nere till vänster','Bottom right'=>'Nere till höger','Repeated across the image'=>'Upprepad över hela bilden','Display copies'=>'Visningskopior','SnapOtter'=>'SnapOtter','Proofing'=>'Bildurval','Visitors'=>'Besökare','Settings sections'=>'Avsnitt i inställningarna','The watermark is stamped on the web copies of images uploaded to galleries that use it. Originals are never changed. Changes apply to images uploaded afterwards; for earlier photos, use Make new copies on a gallery’s Photos tab. 360° panoramas are not watermarked.'=>'Vattenstämpeln läggs på webbkopiorna av bilder som laddas upp till gallerier som använder den. Originalen ändras aldrig. Ändringar gäller bilder som laddas upp efteråt; för tidigare bilder använder du Gör nya kopior på galleriets flik Bilder. 360°-panoramor får ingen vattenstämpel.','Watermark image'=>'Bild för vattenstämpel','None'=>'Ingen','A PNG with a transparent background, uploaded to the media library.'=>'En PNG med genomskinlig bakgrund, uppladdad till mediabiblioteket.','Watermark preview'=>'Förhandsvisning av vattenstämpeln','Use by default'=>'Använd som standard','Watermark new galleries unless a gallery says otherwise'=>'Vattenstämpla nya gallerier om inte galleriet säger något annat','Position'=>'Placering','Size (% of image width)'=>'Storlek (% av bildens bredd)','Opacity (%)'=>'Opacitet (%)','Public gallery directory'=>'Offentlig gallerikatalog','Gallery directory page'=>'Sida för gallerikatalogen','Use the theme’s gallery archive'=>'Använd temats galleriarkiv','Choose a public page with the following shortcode. Visitors who open the gallery archive will land on that page.'=>'Välj en offentlig sida med följande kortkod. Besökare som öppnar galleriarkivet hamnar på den sidan.','Upload one full-size original per image. Visitors see a display copy; the original is stored privately for downloads and sales. Changes apply to images uploaded afterwards; for earlier photos, use Make new copies on a gallery’s Photos tab.'=>'Ladda upp ett original i full storlek per bild. Besökarna ser en visningskopia; originalet sparas privat för nedladdningar och försäljning. Ändringar gäller bilder som laddas upp efteråt; för tidigare bilder använder du Gör nya kopior på galleriets flik Bilder.','Longest side (pixels)'=>'Längsta sida (pixlar)','2560 suits most screens. 360° panoramas keep up to 8192 pixels.'=>'2560 passar de flesta skärmar. 360°-panoramor behåller upp till 8192 pixlar.','Upload size'=>'Uppladdningsstorlek','The gallery’s photo uploader transfers files in pieces. The WordPress media library uses this server’s normal upload limit of %s.'=>'Galleriets bilduppladdare skickar filer i delar. WordPress mediabibliotek använder serverns vanliga uppladdningsgräns på %s.','Image processing with SnapOtter'=>'Bildbehandling med SnapOtter','Use SnapOtter for'=>'Använd SnapOtter för','RAW, HEIC, TIFF, PSD and very large images'=>'RAW, HEIC, TIFF, PSD och mycket stora bilder','All gallery uploads'=>'Alla uppladdningar till gallerier','Nothing (WordPress makes all display copies)'=>'Ingenting (WordPress gör alla visningskopior)','Applies when a SnapOtter server is connected. If SnapOtter cannot be reached, WordPress makes the copy itself for JPEG, PNG, WebP and AVIF.'=>'Gäller när en SnapOtter-server är ansluten. Om SnapOtter inte kan nås gör WordPress kopian själv för JPEG, PNG, WebP och AVIF.','“Very large” from (megapixels)'=>'”Mycket stor” från (megapixlar)','Confirmation'=>'Bekräftelse','Email clients a copy of the selection they send'=>'Mejla kunderna en kopia av urvalet de skickar','Goes to the email address of the client’s account and lists the chosen file names, notes and message. Replies go to the gallery’s author. You are always emailed when a selection arrives.'=>'Skickas till e-postadressen för kundens konto och listar de valda filnamnen, anteckningarna och meddelandet. Svar går till galleriets författare. Du får alltid ett mejl när ett urval kommer in.','SlashPhoto never stores IP addresses or browser details. What it can store about visitors is listed here and in the suggested privacy policy text.'=>'SlashPhoto sparar aldrig IP-adresser eller uppgifter om webbläsare. Det som kan sparas om besökare står här och i det föreslagna texten för integritetspolicyn.','Statistics'=>'Statistik','Count how often galleries and photos are viewed'=>'Räkna hur ofta gallerier och bilder visas','Anonymous daily totals only: no cookies, no IP addresses, nothing that identifies a visitor. Your own views and those of search robots are not counted.'=>'Bara anonyma dagliga totaler: inga kakor, inga IP-adresser, inget som identifierar en besökare. Dina egna visningar och sökrobotars räknas inte.','Terms'=>'Villkor','Ask visitors who are not logged in for their email address when they accept a gallery’s terms'=>'Be besökare som inte är inloggade om e-postadress när de godkänner ett galleris villkor','Every acceptance is logged with the date, the wording that was accepted and the account or email address, so you can show who agreed to what.'=>'Varje godkännande loggas med datum, den text som godkändes och kontot eller e-postadressen, så att du kan visa vem som godkände vad.','Sign-in links'=>'Inloggningslänkar','Let clients sign in with an emailed link instead of a password'=>'Låt kunder logga in med en länk i ett mejl i stället för ett lösenord','Client-only galleries offer to email a sign-in link, and invitations to them include one. Links work once and expire. Accounts that can edit content, such as yours, always use their password.'=>'Gallerier för utvalda kunder erbjuder att mejla en inloggningslänk, och inbjudningar till dem innehåller en. Länkarna fungerar en gång och går ut. Konton som kan redigera innehåll, som ditt, använder alltid sitt lösenord.','Keep the visitor log for (days)'=>'Spara besöksloggen i (dagar)','Email addresses given to open a gallery and terms acceptances are deleted after this many days; 0 keeps them. View counts contain nothing personal and are kept.'=>'E-postadresser som lämnats för att öppna ett galleri och godkända villkor raderas efter så här många dagar; 0 sparar dem. Visningsräkningar innehåller inget personligt och sparas.','Shop settings'=>'Butiksinställningar','You are not allowed to change these settings.'=>'Du har inte behörighet att ändra de här inställningarna.','PayPal'=>'PayPal','Customers approve the payment on paypal.com with their PayPal account or a card, then return to your site where the payment is completed. No PayPal script is loaded on your pages.'=>'Kunderna godkänner betalningen på paypal.com med sitt PayPal-konto eller ett kort och kommer sedan tillbaka till din webbplats där betalningen slutförs. Inget skript från PayPal laddas på dina sidor.','Saved. PayPal accepted the credentials.'=>'Sparat. PayPal godkände uppgifterna.','The PayPal credentials were removed.'=>'PayPal-uppgifterna har tagits bort.','Not connected.'=>'Inte ansluten.','Connected to the PayPal sandbox: no real money is charged.'=>'Ansluten till PayPals sandlåda: inga riktiga pengar dras.','Connected, live payments.'=>'Ansluten, riktiga betalningar.','Client ID'=>'Klient-ID','developer.paypal.com → Apps & Credentials → your REST app.'=>'developer.paypal.com → Apps & Credentials → din REST-app.','Secret'=>'Hemlighet','Saved. Enter a new secret to replace it.'=>'Sparad. Ange en ny hemlighet för att byta ut den.','Environment'=>'Miljö','Sandbox (test payments)'=>'Sandlåda (testbetalningar)','Webhook ID'=>'Webhook-ID','Recommended. In your PayPal app add a webhook with this address and the events Checkout order approved, Payment capture completed, denied and refunded, then paste its ID:'=>'Rekommenderas. Lägg till en webhook med den här adressen i din PayPal-app, med händelserna Checkout order approved, Payment capture completed, denied och refunded, och klistra sedan in dess ID:','Save PayPal settings'=>'Spara PayPal-inställningar','Remove credentials'=>'Ta bort uppgifterna','Mollie'=>'Mollie','Customers pay on Mollie’s checkout page with the methods you switch on in the Mollie Dashboard: cards, iDEAL, Bancontact, Klarna, PayPal and more. No Mollie script is loaded on your pages.'=>'Kunderna betalar på Mollies betalsida med de metoder du slår på i Mollies instrumentpanel: kort, iDEAL, Bancontact, Klarna, PayPal med flera. Inget skript från Mollie laddas på dina sidor.','Saved. Mollie accepted the key.'=>'Sparat. Mollie godkände nyckeln.','The Mollie key was removed.'=>'Mollie-nyckeln har tagits bort.','Connected in test mode: no real money is charged.'=>'Ansluten i testläge: inga riktiga pengar dras.','API key'=>'API-nyckel','Saved. Enter a new key to replace it.'=>'Sparad. Ange en ny nyckel för att byta ut den.','Mollie Dashboard → Developers → API keys. Stored encrypted.'=>'Mollies instrumentpanel → Developers → API keys. Sparas krypterad.','This site’s address is not reachable from the internet, so Mollie cannot send payment updates; payments are confirmed when customers return to the site.'=>'Webbplatsens adress kan inte nås från internet, så Mollie kan inte skicka betalningsuppdateringar; betalningarna bekräftas när kunderna kommer tillbaka till webbplatsen.','Save Mollie key'=>'Spara Mollie-nyckeln','Remove key'=>'Ta bort nyckeln','Pages'=>'Sidor','Prices and VAT'=>'Priser och moms','Print templates'=>'Printmallar','Downloads'=>'Nedladdningar','Receipts'=>'Kvitton','Payments'=>'Betalningar','Sell downloads of your originals and prints in different sizes. Assign a price list under the gallery’s settings. Sub-galleries use the same list unless you choose another.'=>'Sälj nedladdningar av dina original och prints i olika storlekar. Välj en prislista i galleriets inställningar. Undergallerier använder samma lista om du inte väljer en annan.','Customers cannot check out until there is a cart page.'=>'Kunderna kan inte gå till kassan förrän det finns en sida för varukorgen.','Create the cart page'=>'Skapa sidan för varukorgen','There are no price lists yet.'=>'Det finns inga prislistor ännu.','Add a price list'=>'Lägg till en prislista','Cart page'=>'Sida för varukorgen','— None —'=>'— Ingen —','A page containing %s. It shows the cart, the checkout form and, through the link customers get by email, their orders and downloads.'=>'En sida som innehåller %s. Den visar varukorgen, kassaformuläret och, via länken som kunderna får i mejl, deras ordrar och nedladdningar.','Terms of purchase'=>'Köpvillkor','If you choose a page, customers must accept it before ordering.'=>'Om du väljer en sida måste kunderna godkänna den innan de beställer.','Currency'=>'Valuta','Prices are not converted if you change this later.'=>'Priserna räknas inte om om du ändrar detta senare.','Prices'=>'Priser','Prices include VAT'=>'Priserna inkluderar moms','VAT rate (%)'=>'Momssats (%)','The rate for your own country and for every country without a rate of its own below; 0 if you do not charge VAT. Shown on receipts. Check the rules for your country.'=>'Satsen för ditt eget land och för alla länder som inte har en egen sats nedan; 0 om du inte tar ut moms. Visas på kvitton. Kontrollera reglerna i ditt land.','VAT by country'=>'Moms per land','Optional, for example when you sell across the EU through the One-Stop Shop (OSS): one country code and rate per line. Prints are charged the rate of the delivery country; for downloads, customers choose the country they live in at checkout. Leave empty to use the rate above everywhere. Prices that include VAT stay the same; the VAT part changes.'=>'Valfritt, till exempel när du säljer inom EU via OSS (One-Stop Shop): en landskod och sats per rad. Prints får leveranslandets sats; för nedladdningar väljer kunderna i kassan vilket land de bor i. Lämna tomt för att använda satsen ovan överallt. Priser som inkluderar moms förblir desamma; momsdelen ändras.','Default price list'=>'Standardprislista','None: only galleries with their own price list sell images'=>'Ingen: bara gallerier med en egen prislista säljer bilder','Manage price lists'=>'Hantera prislistor','Paper and framing templates'=>'Mallar för papper och inramning','Choose which starter templates appear in the price-list editor. When you apply a template, keep the combinations your lab offers in that size and enter your own prices.'=>'Välj vilka startmallar som visas i prislisteredigeraren. När du använder en mall behåller du de kombinationer ditt labb erbjuder i den storleken och anger dina egna priser.','Available print templates'=>'Tillgängliga printmallar','View %s reference'=>'Visa referens för %s','Prints and shipping'=>'Prints och frakt','Shipping per order'=>'Frakt per order','Free shipping from'=>'Fri frakt från','Order value; 0 means never free.'=>'Ordervärde; 0 betyder aldrig fri frakt.','Ship to countries'=>'Skicka till länder','Available for (days)'=>'Tillgängliga i (dagar)','Counted from payment; 0 means no end date. Customers download the original file you uploaded, through a private link that only works for paid orders.'=>'Räknas från betalningen; 0 betyder inget slutdatum. Kunderna laddar ner originalfilen du laddade upp, via en privat länk som bara fungerar för betalda ordrar.','Customers buy gift cards on any page that contains %s, pay for them like other orders and receive the codes when the payment has arrived. A gift card pays for photos, prints and shipping at checkout; it is not a sale itself, so no VAT is charged on it and discount codes do not apply.'=>'Kunderna köper presentkort på alla sidor som innehåller %s, betalar dem som andra ordrar och får koderna när betalningen har kommit in. Ett presentkort betalar för bilder, prints och frakt i kassan; det är ingen försäljning i sig, så ingen moms tas ut på det och rabattkoder gäller inte.','See gift cards and create one by hand'=>'Se presentkort och skapa ett för hand','Sell gift cards'=>'Sälj presentkort','Offer gift cards in the shop'=>'Erbjud presentkort i butiken','Amounts (%s)'=>'Belopp (%s)','Up to eight amounts, separated by commas.'=>'Upp till åtta belopp, separerade med kommatecken.','Valid for (months)'=>'Giltiga i (månader)','Counted from issue; 0 means they never expire. Check the minimum your country requires.'=>'Räknas från utfärdandet; 0 betyder att de aldrig går ut. Kontrollera vilken lägsta giltighetstid ditt land kräver.','Receipts and invoices'=>'Kvitton och fakturor','Customers can open and print a receipt for paid orders, and an invoice while a manual payment is outstanding. Check what your country requires on receipts.'=>'Kunderna kan öppna och skriva ut ett kvitto för betalda ordrar, och en faktura medan en manuell betalning är obetald. Kontrollera vad ditt land kräver på kvitton.','Business name'=>'Företagsnamn','Address and registration'=>'Adress och registrering','Address, company registration number, VAT number, contact details. Shown as written.'=>'Adress, organisationsnummer, momsregistreringsnummer, kontaktuppgifter. Visas som det är skrivet.','Note at the bottom'=>'Text längst ner','Payment and notifications'=>'Betalning och aviseringar','Manual payment'=>'Manuell betalning','Customers may order and pay later (invoice, bank transfer, Swish, cash)'=>'Kunderna får beställa och betala senare (faktura, banköverföring, Swish, kontant)','The order waits until you mark it paid; downloads open then.'=>'Ordern väntar tills du markerar den som betald; då öppnas nedladdningarna.','Name at checkout'=>'Namn i kassan','Pay later (invoice or transfer)'=>'Betala senare (faktura eller överföring)','Payment details'=>'Betalningsuppgifter','Shown on the order page and in the order email, e.g. “Swish 123 456 78 90, mark the payment with your order number.”'=>'Visas på ordersidan och i ordermejlet, t.ex. ”Swish 123 456 78 90, märk betalningen med ditt ordernummer.”','Order notifications to'=>'Orderaviseringar till','No countries selected. Choose a country to accept print orders.'=>'Inga länder valda. Välj ett land för att ta emot printbeställningar.','Choose countries'=>'Välj länder','Search countries'=>'Sök länder','No matching countries.'=>'Inga matchande länder.','Card payments with Stripe'=>'Kortbetalningar med Stripe','Customers pay on Stripe’s own checkout page with card, or with Swish, Klarna and other methods you switch on in the Stripe Dashboard. Card details never reach this site, no Stripe scripts are loaded on your pages and SlashPhoto adds no fees.'=>'Kunderna betalar på Stripes egen betalsida med kort, eller med Swish, Klarna och andra metoder som du slår på i Stripes instrumentpanel. Kortuppgifterna når aldrig webbplatsen, inga skript från Stripe laddas på dina sidor och SlashPhoto lägger inte till några avgifter.','The Stripe keys were removed.'=>'Stripe-nycklarna har tagits bort.','Saved. Stripe accepted the key.'=>'Sparat. Stripe godkände nyckeln.','Secret key'=>'Hemlig nyckel','Stripe Dashboard → Developers → API keys. A restricted key needs write access to Checkout Sessions. Stored encrypted.'=>'Stripes instrumentpanel → Developers → API keys. En begränsad nyckel behöver skrivrätt till Checkout Sessions. Sparas krypterad.','Webhook signing secret'=>'Signeringshemlighet för webhook','Recommended. In the Stripe Dashboard add a webhook endpoint with this address and the events checkout.session.completed, checkout.session.async_payment_succeeded, checkout.session.async_payment_failed and checkout.session.expired:'=>'Rekommenderas. Lägg till en webhook-slutpunkt med den här adressen i Stripes instrumentpanel, med händelserna checkout.session.completed, checkout.session.async_payment_succeeded, checkout.session.async_payment_failed och checkout.session.expired:','Without it, orders are marked paid when the customer returns to your site after paying.'=>'Utan den markeras ordrar som betalda när kunden kommer tillbaka till din webbplats efter betalningen.','Save Stripe keys'=>'Spara Stripe-nycklar','Remove keys'=>'Ta bort nycklarna','SnapOtter connection'=>'Anslutning till SnapOtter','<a href="https://github.com/snapotter-hq/SnapOtter">SnapOtter</a> is a free image toolkit you run on your own server or computer. When it is connected, SlashPhoto sends originals there to make display copies, so RAW, HEIC, TIFF and PSD files work and very large images do not strain your web host. Images are sent only to the address you enter here.'=>'<a href="https://github.com/snapotter-hq/SnapOtter">SnapOtter</a> är en gratis bildverktygslåda som du kör på din egen server eller dator. När den är ansluten skickar SlashPhoto original dit för att göra visningskopior, så att RAW-, HEIC-, TIFF- och PSD-filer fungerar och mycket stora bilder inte belastar ditt webbhotell. Bilderna skickas bara till adressen du anger här.','SnapOtter was disconnected.'=>'SnapOtter har kopplats från.','SnapOtter is connected and working.'=>'SnapOtter är anslutet och fungerar.','Server'=>'Server','Connected (SnapOtter %1$s), last checked %2$s'=>'Ansluten (SnapOtter %1$s), senast kontrollerad %2$s','Uses the API key you entered.'=>'Använder API-nyckeln du angav.','Uses an API key SlashPhoto created; it is deleted from SnapOtter when you disconnect.'=>'Använder en API-nyckel som SlashPhoto skapade; den raderas från SnapOtter när du kopplar från.','Test connection'=>'Testa anslutningen','Disconnect'=>'Koppla från','Server address'=>'Serveradress','The address your web server uses to reach SnapOtter. Use https:// when the traffic crosses the internet.'=>'Adressen som din webbserver använder för att nå SnapOtter. Använd https:// när trafiken går över internet.','Sign in'=>'Logga in','User name'=>'Användarnamn','Password'=>'Lösenord','Used once to create an API key named “SlashPhoto”. The password is not stored.'=>'Används en gång för att skapa en API-nyckel med namnet ”SlashPhoto”. Lösenordet sparas inte.','Connect with user name and password'=>'Anslut med användarnamn och lösenord','Or an API key'=>'Eller en API-nyckel','Create one in SnapOtter under Settings → API Keys. You can limit it to using tools.'=>'Skapa en i SnapOtter under Settings → API Keys. Du kan begränsa den till att använda verktyg.','Connect with API key'=>'Anslut med API-nyckel','Privacy: SnapOtter sends anonymous usage statistics (which tools ran, never files or file names) to its developers unless you switch this off in SnapOtter under Settings → System Settings. Processed files stay on your SnapOtter server until its regular clean-up.'=>'Integritet: SnapOtter skickar anonym användningsstatistik (vilka verktyg som körts, aldrig filer eller filnamn) till sina utvecklare om du inte stänger av det i SnapOtter under Settings → System Settings. Bearbetade filer ligger kvar på din SnapOtter-server tills den städar regelbundet.','VAT report from'=>'Momsrapport från','to'=>'till','Download VAT report (CSV)'=>'Ladda ner momsrapport (CSV)','You cannot export orders.'=>'Du kan inte exportera ordrar.','Choose a start date on or before the end date.'=>'Välj ett startdatum som är samma dag som eller före slutdatumet.','Full-size originals, also RAW, HEIC, TIFF and PSD. SnapOtter makes the display copies.'=>'Original i full storlek, även RAW, HEIC, TIFF och PSD. SnapOtter gör visningskopiorna.','Full-size originals (JPEG, PNG, WebP, AVIF). Display copies are made automatically.'=>'Original i full storlek (JPEG, PNG, WebP, AVIF). Visningskopior görs automatiskt.','Choose photos to upload'=>'Välj bilder att ladda upp','Gave email address'=>'Lämnade e-postadress','Accepted terms'=>'Godkände villkor','Visitor log'=>'Besökslogg','Email addresses visitors gave to open galleries with an email request, and acceptances of gallery terms. No IP addresses or browser details are stored.'=>'E-postadresser som besökare har lämnat för att öppna gallerier med e-postförfrågan, och godkännanden av gallerivillkor. Inga IP-adresser eller uppgifter om webbläsare sparas.','Entries are deleted after %d days (Settings → Visitors).'=>'Posterna raderas efter %d dagar (Inställningar → Besökare).','Entries are kept until you delete them (Settings → Visitors).'=>'Posterna sparas tills du raderar dem (Inställningar → Besökare).','Type'=>'Typ','All entries'=>'Alla poster','Gallery: %s'=>'Galleri: %s','Search email addresses'=>'Sök e-postadresser','Email address'=>'E-postadress','Entry'=>'Post','Email'=>'E-post','Account'=>'Konto','No entries.'=>'Inga poster.','Wording %s'=>'Text %s','The wording fingerprint changes when you change a gallery’s terms, so you can tell which version someone accepted. Visitors can ask for their entries through Tools → Export Personal Data and Erase Personal Data.'=>'Textens fingeravtryck ändras när du ändrar ett galleris villkor, så att du kan se vilken version någon godkände. Besökare kan be om sina poster via Verktyg → Exportera personuppgifter och Radera personuppgifter.','You are not allowed to see visitors.'=>'Du har inte behörighet att se besökare.','Activity in the last 30 days'=>'Aktivitet de senaste 30 dagarna','Activity by account'=>'Aktivitet per konto','Email gate and terms events, up to 10 accounts with the most activity.'=>'Händelser för e-postförfrågan och villkor, upp till 10 konton med mest aktivitet.','No account activity in this period.'=>'Ingen kontoaktivitet under perioden.','Deleted account'=>'Raderat konto','Events without a signed-in account: %s'=>'Händelser utan inloggat konto: %s','Gallery views without visitor identifiers'=>'Gallerivisningar utan besökaridentitet','All counted gallery views share one total. Individual viewers cannot be identified from these counts.'=>'Alla räknade gallerivisningar ingår i en gemensam total. Enskilda besökare kan inte identifieras utifrån räkningarna.','Gallery views per day'=>'Gallerivisningar per dag','Counting is switched off under SlashPhoto → Settings → Visitors.'=>'Räkningen är avstängd under SlashPhoto → Inställningar → Besökare.','Daily views of gallery pages and lightbox photos. Totals include views of content that has since been removed. Editors and robots are excluded.'=>'Dagliga visningar av gallerisidor och bilder i bildvisaren. Totalerna inkluderar visningar av innehåll som sedan har tagits bort. Redaktörer och robotar räknas inte.','Statistics period'=>'Statistikperiod','Last %d day'=>'Senaste %d dagen' . "\0" . 'Senaste %d dagarna','Photo views per day'=>'Bildvisningar per dag','Page views'=>'Sidvisningar','Photo views'=>'Bildvisningar','Most viewed photos'=>'Mest visade bilder','Photo'=>'Bild','Removed gallery'=>'Borttaget galleri','Image viewer'=>'Bildvisare','Close'=>'Stäng','Previous image'=>'Föregående bild','Next image'=>'Nästa bild','%1$d of %2$d'=>'%1$d av %2$d','Loading…'=>'Laddar…','360° panorama. Drag to look around.'=>'360°-panorama. Dra för att se dig omkring.','Your browser cannot show 360° images. Showing the flat image instead.'=>'Din webbläsare kan inte visa 360°-bilder. Den platta bilden visas i stället.','Fullscreen'=>'Helskärm','Add to selection'=>'Lägg till i urvalet','Remove from selection'=>'Ta bort från urvalet','%d selected'=>'%d valda','%1$d of %2$d selected'=>'%1$d av %2$d valda','Favourites: %d, saved in this browser only.'=>'Favoriter: %d, sparade bara i den här webbläsaren.','Log in to send them to the photographer'=>'Logga in för att skicka dem till fotografen','Show only selected'=>'Visa bara valda','Send selection…'=>'Skicka urvalet…','Send to the photographer'=>'Skicka till fotografen','Cancel'=>'Avbryt','Message to the photographer (optional)'=>'Meddelande till fotografen (valfritt)','After sending, the selection is locked. The photographer can open it again if you need to change it.'=>'När urvalet har skickats låses det. Fotografen kan öppna det igen om du behöver ändra något.','Selection sent on %2$s (%1$d selected).'=>'Urvalet skickades %2$s (%1$d valda).','Note'=>'Anteckning','Note for the photographer about this image'=>'Anteckning till fotografen om den här bilden','Save'=>'Spara','Your selection could not be saved. Check your connection and try again.'=>'Ditt urval kunde inte sparas. Kontrollera anslutningen och försök igen.','Your selection'=>'Ditt urval','Cart'=>'Varukorg','Buy this photo'=>'Köp den här bilden','Cart: %d item'=>'Varukorg: %d artikel','Cart: %d items'=>'Varukorg: %d artiklar','Open a photo to order prints or downloads.'=>'Öppna en bild för att beställa prints eller nedladdningar.','Go to cart'=>'Gå till varukorgen','Add'=>'Lägg till','Add %s to cart'=>'Lägg %s i varukorgen','Added: %s.'=>'Tillagt: %s.','Quantity, %s'=>'Antal, %s','Paper and framing'=>'Papper och inramning','Paper and framing, %s'=>'Papper och inramning, %s','Your cart is empty.'=>'Varukorgen är tom.','Some photos or options are no longer available and were removed from the cart.'=>'Vissa bilder eller alternativ finns inte längre och har tagits bort från varukorgen.','Remove'=>'Ta bort','Remove %s'=>'Ta bort %s','Subtotal'=>'Delsumma','Fill in the marked fields.'=>'Fyll i de markerade fälten.','%1$d photos you choose, each: %2$s'=>'%1$d bilder som du väljer, var och en: %2$s','Every photo in this gallery, each: %s'=>'Alla bilder i det här galleriet, var och en: %s','Add to package'=>'Lägg i paketet','Add this photo to %s'=>'Lägg den här bilden i %s','Added to %1$s: %2$d of %3$d photos.'=>'Tillagd i %1$s: %2$d av %3$d bilder.','This photo is already in %s.'=>'Den här bilden finns redan i %s.','%s is already in your cart.'=>'%s finns redan i varukorgen.','%1$d of %2$d photos chosen. Open more photos to add them.'=>'%1$d av %2$d bilder valda. Öppna fler bilder för att lägga till dem.','%1$d of %2$d photos chosen.'=>'%1$d av %2$d bilder valda.','All %d photos'=>'Alla %d bilder','Remove %s from the package'=>'Ta bort %s från paketet','Code %s applied.'=>'Koden %s har lagts till.','Gift card applied.'=>'Presentkortet har lagts till.','Something went wrong. Check your connection and try again.'=>'Något gick fel. Kontrollera anslutningen och försök igen.','Upload not found.'=>'Uppladdningen hittades inte.','RAW, HEIC, TIFF and PSD files need a SnapOtter server. Connect one under SlashPhoto → Settings, or upload JPEG files.'=>'RAW-, HEIC-, TIFF- och PSD-filer kräver en SnapOtter-server. Anslut en under SlashPhoto → Inställningar, eller ladda upp JPEG-filer.','This file type cannot be added to a gallery.'=>'Den här filtypen kan inte läggas till i ett galleri.','The file is larger than this site accepts.'=>'Filen är större än webbplatsen tar emot.','The upload folder could not be created.'=>'Uppladdningsmappen kunde inte skapas.','There is not enough free disk space for this file.'=>'Det finns inte tillräckligt med ledigt diskutrymme för filen.','The upload is out of step. Resume from the size given.'=>'Uppladdningen är i otakt. Fortsätt från den angivna storleken.','Invalid upload chunk.'=>'Ogiltig del av uppladdningen.','The chunk could not be saved.'=>'Delen kunde inte sparas.','The upload is not complete.'=>'Uppladdningen är inte klar.','Photo client'=>'Fotokund','The file is not an image WordPress can read.'=>'Filen är inte en bild som WordPress kan läsa.','SnapOtter is not connected.'=>'SnapOtter är inte anslutet.','Edit gallery'=>'Redigera galleri','New gallery'=>'Nytt galleri','Search galleries'=>'Sök gallerier','No galleries found.'=>'Inga gallerier hittades.','No galleries found in Trash.'=>'Inga gallerier hittades i papperskorgen.','Parent gallery:'=>'Överordnat galleri:','%s (from Sunshine)'=>'%s (från Sunshine)','Gallery “%1$s” could not be created: %2$s'=>'Galleriet ”%1$s” kunde inte skapas: %2$s','Gallery “%1$s” had the password hint “%2$s”, which was not imported.'=>'Galleriet ”%1$s” hade lösenordstipset ”%2$s”, som inte importerades.','Image %1$s was not imported: %2$s'=>'Bilden %1$s importerades inte: %2$s','the file is missing.'=>'filen saknas.','the file could not be copied.'=>'filen kunde inte kopieras.','Imported from Sunshine order %1$s (payment: %2$s).'=>'Importerad från Sunshine-order %1$s (betalning: %2$s).','detected: 360°'=>'identifierad: 360°','detected: not 360°'=>'identifierad: inte 360°','Automatic (%s)'=>'Automatiskt (%s)','360° panorama'=>'360°-panorama','Not 360°'=>'Inte 360°','Panorama'=>'Panorama','Only gallery photos can be processed again.'=>'Bara bilder i gallerier kan bearbetas igen.','The original file is missing.'=>'Originalfilen saknas.','RAW, HEIC, TIFF and PSD originals need a connected SnapOtter server.'=>'RAW-, HEIC-, TIFF- och PSD-original kräver en ansluten SnapOtter-server.','The gallery folder cannot be written.'=>'Det går inte att skriva i galleriets mapp.','New copies could not be made; the photo was left unchanged.'=>'Nya kopior kunde inte göras; bilden lämnades oförändrad.','The original could not be read.'=>'Originalet kunde inte läsas.','Suggested text from SlashPhoto. It describes the plugin as shipped; review it if you add other plugins.'=>'Föreslagen text från SlashPhoto. Den beskriver tillägget som det levereras; gå igenom den om du lägger till andra tillägg.','Our photo galleries never store IP addresses or browser details, use no third-party analytics or tracking, and do not load anything from other websites.'=>'Våra fotogallerier sparar aldrig IP-adresser eller uppgifter om webbläsare, använder ingen analys eller spårning från tredje part och laddar inget från andra webbplatser.','We count how often each gallery and photo is viewed, as anonymous daily totals. No cookie is set and nothing that identifies you is stored.'=>'Vi räknar hur ofta varje galleri och bild visas, som anonyma dagliga totaler. Ingen kaka sätts och inget som identifierar dig sparas.','We keep it for %d days.'=>'Vi sparar den i %d dagar.','We keep it until you ask us to delete it.'=>'Vi sparar den tills du ber oss radera den.','Some galleries ask for your email address before showing photos. We store the address you give, the gallery and the date, so we know who has seen the photos, and a cookie (slashphoto_email_…) remembers it in your browser for 30 days. If you are logged in, we note your account instead of asking.'=>'Vissa gallerier ber om din e-postadress innan bilderna visas. Vi sparar adressen du anger, galleriet och datumet, så att vi vet vem som har sett bilderna, och en kaka (slashphoto_email_…) kommer ihåg det i din webbläsare i 30 dagar. Om du är inloggad noterar vi ditt konto i stället för att fråga.','When you open a password-protected gallery, WordPress stores a cookie (wp-postpass) containing a scrambled form of the password, for up to 10 days.'=>'När du öppnar ett lösenordsskyddat galleri sparar WordPress en kaka (wp-postpass) med lösenordet i omvandlad form, i upp till 10 dagar.','When you accept a gallery’s terms, a cookie (slashphoto_terms_…) remembers this in your browser for 30 days, and we record the acceptance with the date, which wording you accepted and your account or email address, so we can show what was agreed.'=>'När du godkänner ett galleris villkor kommer en kaka (slashphoto_terms_…) ihåg det i din webbläsare i 30 dagar, och vi registrerar godkännandet med datum, vilken text du godkände och ditt konto eller din e-postadress, så att vi kan visa vad som avtalades.','When you open a gallery through a private link, a cookie (slashphoto_link_…) remembers this in your browser for 30 days. It contains only a signature of the gallery and the link; nothing about you is stored on our server.'=>'När du öppnar ett galleri via en privat länk kommer en kaka (slashphoto_link_…) ihåg det i din webbläsare i 30 dagar. Den innehåller bara en signatur av galleriet och länken; inget om dig sparas på vår server.','If you mark favourites without being logged in, they are kept only in your own browser (local storage) and never sent to us.'=>'Om du markerar favoriter utan att vara inloggad sparas de bara i din egen webbläsare (lokal lagring) och skickas aldrig till oss.','If you choose images while logged in, we store your choice, any notes you write and the message you send with it, together with your account, so we can deliver your photos. It is deleted with your account or when we delete the gallery, and you can ask for a copy or for it to be erased.'=>'Om du väljer bilder när du är inloggad sparar vi ditt val, eventuella anteckningar och meddelandet du skickar med, tillsammans med ditt konto, så att vi kan leverera dina bilder. Det raderas med ditt konto eller när vi raderar galleriet, och du kan be om en kopia eller om att det raderas.','Your shopping cart is kept only in your own browser (local storage) until you order.'=>'Din varukorg sparas bara i din egen webbläsare (lokal lagring) tills du beställer.','When you order, we store your name, email address, phone number if you give it, delivery address for prints, your message and what you bought, to deliver the order and for our bookkeeping. Orders that are never paid are deleted after a week. Paid orders are kept as long as accounting law requires.'=>'När du beställer sparar vi ditt namn, din e-postadress, ditt telefonnummer om du anger det, leveransadress för prints, ditt meddelande och vad du köpte, för att leverera ordern och för vår bokföring. Ordrar som aldrig betalas raderas efter en vecka. Betalda ordrar sparas så länge bokföringslagen kräver.','If you pay online, you enter your payment details on the page of our payment provider, not on this site: %s. The provider receives your email address (Stripe), the order lines and the amount, and processes the payment under its own privacy policy.'=>'Om du betalar online anger du dina betalningsuppgifter på vår betalningsleverantörs sida, inte på den här webbplatsen: %s. Leverantören får din e-postadress (Stripe), orderraderna och beloppet, och hanterar betalningen enligt sin egen integritetspolicy.','If we give you a client account, your name, email address and the galleries you may see are stored in that account until you ask us to delete it.'=>'Om vi ger dig ett kundkonto sparas ditt namn, din e-postadress och de gallerier du får se i kontot tills du ber oss radera det.','Photo selections'=>'Bildurval','Photo gallery visitor log'=>'Besökslogg för fotogallerier','Photo orders'=>'Fotobeställningar','Images'=>'Bilder','Message'=>'Meddelande','Sent'=>'Skickat','Name'=>'Namn','Phone'=>'Telefon','Items'=>'Artiklar','Paid photo orders were kept because they are bookkeeping records.'=>'Betalda fotobeställningar sparades eftersom de är bokföringsunderlag.','Gave email address to open the gallery'=>'Lämnade e-postadress för att öppna galleriet','Accepted the gallery terms'=>'Godkände galleriets villkor','A client'=>'En kund','[%1$s] New selection for %2$s'=>'[%1$s] Nytt urval för %2$s','%1$s has sent a selection of %2$d image from "%3$s".'=>'%1$s har skickat ett urval med %2$d bild från ”%3$s”.' . "\0" . '%1$s har skickat ett urval med %2$d bilder från ”%3$s”.','Message:'=>'Meddelande:','See the selection and the file names:'=>'Se urvalet och filnamnen:','[%1$s] Your selection from %2$s'=>'[%1$s] Ditt urval från %2$s','Thank you. Your selection of %1$d image from "%2$s" has been sent to the photographer.'=>'Tack. Ditt urval med %1$d bild från ”%2$s” har skickats till fotografen.' . "\0" . 'Tack. Ditt urval med %1$d bilder från ”%2$s” har skickats till fotografen.','Your message:'=>'Ditt meddelande:','The photographer can reopen the selection if you want to change it.'=>'Fotografen kan öppna urvalet igen om du vill ändra det.','Log in to save your selection.'=>'Logga in för att spara ditt urval.','Your selection could not be saved.'=>'Ditt urval kunde inte sparas.','You can choose at most %d image.'=>'Du kan välja högst %d bild.' . "\0" . 'Du kan välja högst %d bilder.','Choose at least one image first.'=>'Välj minst en bild först.','Gallery not found.'=>'Galleriet hittades inte.','Your selection has been sent. Ask the photographer if you want to change it.'=>'Ditt urval har skickats. Fråga fotografen om du vill ändra det.','The order could not be placed.'=>'Ordern kunde inte läggas.','Your cart has changed: some prices or images are no longer the same. Check it and try again.'=>'Varukorgen har ändrats: vissa priser eller bilder är inte längre desamma. Kontrollera den och försök igen.','Choose the country you live in.'=>'Välj landet du bor i.','Enter your name.'=>'Ange ditt namn.','Enter the delivery address for your prints.'=>'Ange leveransadressen för dina prints.','Prints cannot be sent to that country.'=>'Prints kan inte skickas till det landet.','Accept the terms of purchase to place the order.'=>'Godkänn köpvillkoren för att lägga ordern.','Choose how to pay.'=>'Välj hur du vill betala.','Including VAT (%s %%)'=>'Varav moms (%s %%)','VAT (%s %%)'=>'Moms (%s %%)','Discount codes'=>'Rabattkoder','Discount code'=>'Rabattkod','Add discount code'=>'Lägg till rabattkod','Edit discount code'=>'Redigera rabattkod','Search discount codes'=>'Sök rabattkoder','No discount codes found.'=>'Inga rabattkoder hittades.','No discount codes found in Trash.'=>'Inga rabattkoder hittades i papperskorgen.','This discount code is not valid.'=>'Rabattkoden är inte giltig.','This discount code is not valid right now.'=>'Rabattkoden gäller inte just nu.','This discount code needs an order of at least %s.'=>'Rabattkoden kräver en order på minst %s.','This discount code has been used up.'=>'Rabattkoden är förbrukad.','You have already used this discount code.'=>'Du har redan använt den här rabattkoden.','This discount code does not apply to anything in your cart.'=>'Rabattkoden gäller inget i din varukorg.','Code, e.g. SUMMER20'=>'Kod, t.ex. SOMMAR20','Code'=>'Kod','Used'=>'Använd','free shipping'=>'fri frakt','downloads only'=>'bara nedladdningar','prints only'=>'bara prints','Customers type the code (the title above) in the cart. Publish it to switch it on; save it as a draft to switch it off.'=>'Kunderna skriver koden (titeln ovan) i varukorgen. Publicera den för att slå på den; spara den som utkast för att stänga av den.','Applies to'=>'Gäller','Everything (downloads, prints, packages)'=>'Allt (nedladdningar, prints, paket)','Prints'=>'Prints','Free shipping'=>'Fri frakt','Minimum order'=>'Lägsta ordervärde','Valid'=>'Giltig','From'=>'Från','until'=>'till och med','Both days included. Leave empty for no limit.'=>'Båda dagarna ingår. Lämna tomt för ingen gräns.','Uses in total'=>'Användningar totalt','0 means no limit.'=>'0 betyder ingen gräns.','Uses per customer'=>'Användningar per kund','Counted by email address; 0 means no limit.'=>'Räknas per e-postadress; 0 betyder ingen gräns.','This download link is not valid.'=>'Nedladdningslänken är inte giltig.','This download is not available. It opens when the payment has arrived and closes when the download period ends.'=>'Nedladdningen är inte tillgänglig. Den öppnas när betalningen har kommit in och stängs när nedladdningsperioden är slut.','The file is missing. Please contact us.'=>'Filen saknas. Kontakta oss.','You are not allowed to download this file.'=>'Du har inte behörighet att ladda ner den här filen.','This size cannot be made right now. Please try again later or contact us.'=>'Den här storleken kan inte göras just nu. Försök igen senare eller kontakta oss.','This size cannot be made from the original file. Please contact us.'=>'Den här storleken kan inte göras från originalfilen. Kontakta oss.','[%1$s] Order %2$d received'=>'[%1$s] Order %2$d har tagits emot','Thank you for your order. It is waiting for your payment.'=>'Tack för din beställning. Den väntar på din betalning.','[%1$s] New order %2$d, awaiting payment'=>'[%1$s] Ny order %2$d, väntar på betalning','[%1$s] Payment received for order %2$d'=>'[%1$s] Betalning mottagen för order %2$d','Thank you, we have received your payment.'=>'Tack, vi har tagit emot din betalning.','[%1$s] Order %2$d is paid'=>'[%1$s] Order %2$d är betald','[%1$s] Order %2$d is complete'=>'[%1$s] Order %2$d är klar','Your order is complete. Prints are on their way if you ordered any.'=>'Din order är klar. Prints är på väg om du beställde några.','[%1$s] Order %2$d was cancelled'=>'[%1$s] Order %2$d har avbrutits','Your order was cancelled.'=>'Din order har avbrutits.','[%1$s] Order %2$d was refunded'=>'[%1$s] Order %2$d har återbetalats','Your order was refunded.'=>'Din order har återbetalats.','Your gift cards:'=>'Dina presentkort:','valid until %s'=>'giltigt till %s','Enter a code under "Gift card code" in the cart. Anyone who has a code can use it.'=>'Ange en kod under ”Presentkortskod” i varukorgen. Alla som har en kod kan använda den.','Download your photos here:'=>'Ladda ner dina bilder här:','See your order here:'=>'Se din order här:','Your receipt:'=>'Ditt kvitto:','Your invoice:'=>'Din faktura:','Keep this link to yourself: anyone who has it can see the order.'=>'Behåll länken för dig själv: alla som har den kan se ordern.','Open the order:'=>'Öppna ordern:','Discount (%1$s): −%2$s'=>'Rabatt (%1$s): −%2$s','Discount: −%s'=>'Rabatt: −%s','Shipping: %s'=>'Frakt: %s','Including VAT: %s'=>'Varav moms: %s','VAT: %s'=>'Moms: %s','Total: %s'=>'Totalt: %s','Gift card (…%1$s): −%2$s'=>'Presentkort (…%1$s): −%2$s','To pay: %s'=>'Att betala: %s','Delivery address:'=>'Leveransadress:','Message from the customer:'=>'Meddelande från kunden:','You get payment details by email. Downloads open when the payment has arrived.'=>'Du får betalningsuppgifter i ett mejl. Nedladdningarna öppnas när betalningen har kommit in.','Pay online (Mollie)'=>'Betala online (Mollie)','Card, iDEAL, Bancontact and other methods on Mollie’s secure page.'=>'Kort, iDEAL, Bancontact och andra metoder på Mollies säkra sida.','A Mollie API key starts with live_ or test_ (Mollie Dashboard → Developers → API keys).'=>'En API-nyckel från Mollie börjar med live_ eller test_ (Mollies instrumentpanel → Developers → API keys).','Order %1$d, %2$s'=>'Order %1$d, %2$s','Mollie sent an unexpected answer.'=>'Mollie skickade ett oväntat svar.','The payment has not been confirmed by Mollie yet. If you paid, this page updates within a few minutes.'=>'Betalningen har inte bekräftats av Mollie ännu. Om du har betalat uppdateras sidan inom några minuter.','Mollie is not set up.'=>'Mollie är inte inställt.','Mollie could not be reached. Try again in a moment.'=>'Mollie kunde inte nås. Försök igen om en stund.','Mollie: %s'=>'Mollie: %s','the request was refused.'=>'begäran nekades.','Pay with your PayPal account or a card on PayPal’s page.'=>'Betala med ditt PayPal-konto eller ett kort på PayPals sida.','Enter the client ID and secret of a PayPal REST app (developer.paypal.com → Apps & Credentials).'=>'Ange klient-ID och hemlighet för en REST-app i PayPal (developer.paypal.com → Apps & Credentials).','The webhook ID is shown next to the webhook in your PayPal app.'=>'Webhook-ID:t visas bredvid webhooken i din PayPal-app.','PayPal sent an unexpected answer.'=>'PayPal skickade ett oväntat svar.','The payment has not been confirmed by PayPal yet. If you approved it, this page updates within a few minutes.'=>'Betalningen har inte bekräftats av PayPal ännu. Om du har godkänt den uppdateras sidan inom några minuter.','PayPal could not be reached. Try again in a moment.'=>'PayPal kunde inte nås. Försök igen om en stund.','PayPal did not accept the client ID and secret. Check that they belong to the chosen environment (sandbox or live).'=>'PayPal godkände inte klient-ID och hemlighet. Kontrollera att de hör till den valda miljön (sandlåda eller skarp).','PayPal: %s'=>'PayPal: %s','Pay online'=>'Betala online','Card and other methods. You pay on Stripe’s secure page.'=>'Kort och andra metoder. Du betalar på Stripes säkra sida.','That does not look like a Stripe secret key (sk_live_…, sk_test_… or a restricted rk_… key). Publishable keys (pk_…) do not work here.'=>'Det ser inte ut som en hemlig nyckel från Stripe (sk_live_…, sk_test_… eller en begränsad rk_…-nyckel). Publicerbara nycklar (pk_…) fungerar inte här.','The webhook signing secret starts with whsec_.'=>'Signeringshemligheten för webhooken börjar med whsec_.','VAT %s %%'=>'Moms %s %%','Discount and gift card'=>'Rabatt och presentkort','Gift card'=>'Presentkort','Stripe sent an unexpected answer.'=>'Stripe skickade ett oväntat svar.','The payment has not been confirmed yet. If you paid, this page updates within a few minutes.'=>'Betalningen har inte bekräftats ännu. Om du har betalat uppdateras sidan inom några minuter.','Stripe is not set up.'=>'Stripe är inte inställt.','Stripe could not be reached. Try again in a moment.'=>'Stripe kunde inte nås. Försök igen om en stund.','Stripe refused the request.'=>'Stripe nekade begäran.','Stripe: %s'=>'Stripe: %s','Gift card %s'=>'Presentkort %s','This gift card code is not valid.'=>'Presentkortskoden är inte giltig.','This gift card can no longer be used.'=>'Presentkortet kan inte längre användas.','This gift card has expired.'=>'Presentkortet har gått ut.','This gift card is in another currency.'=>'Presentkortet är i en annan valuta.','This gift card has been used up.'=>'Presentkortet är förbrukat.','Awaiting payment'=>'Väntar på betalning','Awaiting manual payment'=>'Väntar på manuell betalning','Paid, being prepared'=>'Betald, förbereds','Completed'=>'Klar','Cancelled'=>'Avbruten','Refunded'=>'Återbetald','Payment failed'=>'Betalningen misslyckades','The order could not be saved.'=>'Ordern kunde inte sparas.','%d photo'=>'%d bild' . "\0" . '%d bilder','The gift card balance has changed. Check your cart and try again.'=>'Presentkortets saldo har ändrats. Kontrollera varukorgen och försök igen.','Price lists'=>'Prislistor','Add price list'=>'Lägg till prislista','Edit price list'=>'Redigera prislista','New price list'=>'Ny prislista','Search price lists'=>'Sök prislistor','No price lists found.'=>'Inga prislistor hittades.','No price lists found in Trash.'=>'Inga prislistor hittades i papperskorgen.','Unframed'=>'Utan ram','Products'=>'Produkter','Digital download, full resolution'=>'Digital nedladdning, full upplösning','Digital download, web size (2048 px)'=>'Digital nedladdning, webbstorlek (2048 px)','Print 13 × 18 cm'=>'Print 13 × 18 cm','Print 20 × 30 cm'=>'Print 20 × 30 cm','Print 30 × 45 cm'=>'Print 30 × 45 cm','Customers choose one of these for each image. Downloads deliver the original file you uploaded, or a smaller copy of it when you set the longest side. You make and send the prints. Enter a price or configure print options. Use 0 for something free.'=>'Kunderna väljer en av de här för varje bild. Nedladdningar levererar originalfilen du laddade upp, eller en mindre kopia av den om du anger längsta sidan. Du gör och skickar prints själv. Ange ett pris eller ställ in printalternativ. Använd 0 för något som är gratis.','A package is a number of photos the customer chooses, each with the same download or print, for one price, e.g. “10 downloads”. Set the number to 0 for every photo in the gallery. Save new downloads and prints before choosing them in a package.'=>'Ett paket är ett antal bilder som kunden väljer, var och en med samma nedladdning eller print, för ett pris, t.ex. ”10 nedladdningar”. Ange 0 som antal för alla bilder i galleriet. Spara nya nedladdningar och prints innan du väljer dem i ett paket.','Name shown to customers'=>'Namn som visas för kunderna','Price (%s)'=>'Pris (%s)','Add product'=>'Lägg till produkt','Prices include VAT, as set under SlashPhoto → Settings.'=>'Priserna inkluderar moms, enligt SlashPhoto → Inställningar.','VAT is added on top of these prices, as set under SlashPhoto → Settings.'=>'Moms läggs på de här priserna, enligt SlashPhoto → Inställningar.','Print'=>'Print','Package'=>'Paket','each with'=>'var och en med','Longest side (px)'=>'Längsta sida (px)','Leave empty for the full-size original. Smaller originals are never enlarged.'=>'Lämna tomt för originalet i full storlek. Mindre original förstoras aldrig.','Paper and framing options'=>'Alternativ för papper och inramning','Print template'=>'Printmall','Choose a template'=>'Välj en mall','Add combinations'=>'Lägg till kombinationer','Print options'=>'Printalternativ','Enter one available combination per line as Paper | Frame | Full price. Leave the frame blank for an unframed print. The first combination is selected by default.'=>'Ange en tillgänglig kombination per rad som Papper | Ram | Fullt pris. Lämna ramen tom för en print utan ram. Den första kombinationen är förvald.','Price'=>'Pris','The price list was kept as it was. Enter each paper and frame combination once, with a price of zero or more. A print can have up to 24 combinations and each paper or frame name can be up to 36 characters.'=>'Prislistan behölls som den var. Ange varje kombination av papper och ram en gång, med ett pris på noll eller mer. En print kan ha upp till 24 kombinationer och varje namn på papper eller ram kan vara upp till 36 tecken.','Combinations added. Enter a price for each new row.'=>'Kombinationerna har lagts till. Ange ett pris för varje ny rad.','These combinations are already in this print.'=>'De här kombinationerna finns redan för den här printen.','This template would exceed the maximum of 24 combinations per print.'=>'Mallen skulle överskrida högst 24 kombinationer per print.','Enter a price for every paper and frame combination before saving.'=>'Ange ett pris för varje kombination av papper och ram innan du sparar.','Matte photo paper'=>'Matt fotopapper','Black wood frame'=>'Svart träram','Oak frame'=>'Ekram','Giclée fine art paper'=>'Giclée fine art-papper','Fuji Crystal DP II (matte)'=>'Fuji Crystal DP II (matt)','Glossy photo paper'=>'Blankt fotopapper','Fine art paper'=>'Fine art-papper','Fuji Crystal DP II (glossy)'=>'Fuji Crystal DP II (blank)','Fuji Crystal DP II (silk)'=>'Fuji Crystal DP II (silke)','White wood frame'=>'Vit träram','You are not allowed to see orders.'=>'Du har inte behörighet att se ordrar.','Receipt %d'=>'Kvitto %d','Invoice %d'=>'Faktura %d','No payment needed'=>'Ingen betalning behövs','Gift cards cannot be paid for with a gift card.'=>'Presentkort kan inte betalas med ett presentkort.','SnapOtter did not accept the user name or password.'=>'SnapOtter godkände inte användarnamnet eller lösenordet.','This SnapOtter account uses two-factor sign-in. Create an API key in SnapOtter (Settings → API Keys) and connect with the key instead.'=>'Det här SnapOtter-kontot använder tvåstegsinloggning. Skapa en API-nyckel i SnapOtter (Settings → API Keys) och anslut med nyckeln i stället.','SnapOtter answered in an unexpected way.'=>'SnapOtter svarade på ett oväntat sätt.','SnapOtter did not return an API key.'=>'SnapOtter returnerade ingen API-nyckel.','SnapOtter reports that it is not healthy.'=>'SnapOtter rapporterar att det inte mår bra.','SnapOtter did not accept the API key, or the key may not run tools.'=>'SnapOtter godkände inte API-nyckeln, eller så får nyckeln inte köra verktyg.','SnapOtter did not finish the image.'=>'SnapOtter blev inte klart med bilden.','SnapOtter answered with a link to another server; it was not followed.'=>'SnapOtter svarade med en länk till en annan server; den följdes inte.','Could not download the result from SnapOtter (HTTP %d).'=>'Kunde inte hämta resultatet från SnapOtter (HTTP %d).','The uploaded file could not be read.'=>'Den uppladdade filen kunde inte läsas.','Could not reach SnapOtter: %s'=>'Kunde inte nå SnapOtter: %s','SnapOtter answered with an error (HTTP %1$d). %2$s'=>'SnapOtter svarade med ett fel (HTTP %1$d). %2$s','Enter the full address of your SnapOtter server, for example http://192.168.1.10:1349.'=>'Ange den fullständiga adressen till din SnapOtter-server, till exempel http://192.168.1.10:1349.','That does not look like a SnapOtter API key.'=>'Det ser inte ut som en API-nyckel för SnapOtter.','This gallery is only available to invited clients.'=>'Galleriet är bara tillgängligt för inbjudna kunder.','Log in to view the gallery'=>'Logga in för att se galleriet','If that address belongs to an invited client, a sign-in link is on its way. It works once, for one hour.'=>'Om adressen tillhör en inbjuden kund är en inloggningslänk på väg. Den fungerar en gång, i en timme.','No password? Get a sign-in link by email'=>'Inget lösenord? Få en inloggningslänk via e-post','Email me a link'=>'Mejla mig en länk','This gallery is private. Please use the link you received from the photographer.'=>'Galleriet är privat. Använd länken du har fått från fotografen.','This gallery is password protected.'=>'Galleriet är lösenordsskyddat.','Open the gallery'=>'Öppna galleriet','This gallery is no longer available. Please contact the photographer if you need access.'=>'Galleriet är inte längre tillgängligt. Kontakta fotografen om du behöver åtkomst.','Your account does not have access to this gallery. Please contact the photographer if you think this is a mistake.'=>'Ditt konto har inte åtkomst till galleriet. Kontakta fotografen om du tror att det är ett misstag.','The cart needs JavaScript. Please switch it on to order.'=>'Varukorgen behöver JavaScript. Slå på det för att beställa.','Loading your cart…'=>'Laddar varukorgen…','Apply'=>'Använd','Gift card code'=>'Presentkortskod','Use'=>'Lös in','Your details'=>'Dina uppgifter','If the photographer gave you an account, log in first so images from your private galleries can be ordered.'=>'Om fotografen har gett dig ett konto, logga in först så att bilder från dina privata gallerier kan beställas.','Log in'=>'Logga in','Phone (optional)'=>'Telefon (valfritt)','Country you live in'=>'Land du bor i','Choose…'=>'Välj…','Digital downloads are charged the VAT of the country you live in.'=>'Digitala nedladdningar beskattas med momsen i det land du bor i.','Delivery address for prints'=>'Leveransadress för prints','Prints cannot be sent at the moment. Remove them from the cart to order the rest.'=>'Prints kan inte skickas just nu. Ta bort dem från varukorgen för att beställa resten.','Street address'=>'Gatuadress','Apartment, c/o (optional)'=>'Lägenhet, c/o (valfritt)','Postcode'=>'Postnummer','City'=>'Ort','Country'=>'Land','Payment'=>'Betalning','Ordering is not open at the moment.'=>'Det går inte att beställa just nu.','I accept the %s'=>'Jag godkänner %s','terms of purchase'=>'köpvillkoren','Place order'=>'Lägg ordern','We store your details with the order only to deliver it and for our bookkeeping. Orders that are never paid are deleted after a week.'=>'Vi sparar dina uppgifter med ordern bara för att leverera den och för vår bokföring. Ordrar som aldrig betalas raderas efter en vecka.','Enter your email address to see the photos'=>'Ange din e-postadress för att se bilderna','Enter a valid email address and tick the box.'=>'Ange en giltig e-postadress och kryssa i rutan.','I agree that the photographer keeps my email address and the date with this gallery for %d days.'=>'Jag godkänner att fotografen sparar min e-postadress och datumet med det här galleriet i %d dagar.','I agree that the photographer keeps my email address and the date with this gallery.'=>'Jag godkänner att fotografen sparar min e-postadress och datumet med det här galleriet.','Show the photos'=>'Visa bilderna','This browser remembers it for 30 days. No IP address or browser details are stored.'=>'Webbläsaren kommer ihåg det i 30 dagar. Ingen IP-adress eller uppgift om webbläsaren sparas.','Photo galleries'=>'Fotogallerier','Browse the collections, choose your favourites and order prints or downloads from galleries that offer them.'=>'Bläddra bland samlingarna, välj dina favoriter och beställ prints eller nedladdningar från gallerier som erbjuder dem.','Browse galleries'=>'Bläddra bland gallerierna','View cart'=>'Visa varukorgen','Public galleries'=>'Offentliga gallerier','Have a private gallery? Open the link from your photographer.'=>'Har du ett privat galleri? Öppna länken från din fotograf.','All public galleries'=>'Alla offentliga gallerier','No public galleries are available yet.'=>'Det finns inga offentliga gallerier ännu.','panorama badge360°'=>'360°','This gallery has no images yet.'=>'Galleriet har inga bilder ännu.','The code arrives by email when the payment is in, and can be used for photos, prints and downloads for %d month.'=>'Koden kommer via e-post när betalningen har kommit in och kan användas för bilder, prints och nedladdningar i %d månad.' . "\0" . 'Koden kommer via e-post när betalningen har kommit in och kan användas för bilder, prints och nedladdningar i %d månader.','The code arrives by email when the payment is in, and can be used for photos, prints and downloads.'=>'Koden kommer via e-post när betalningen har kommit in och kan användas för bilder, prints och nedladdningar.','This order link is not valid. Use the link in your order email, or contact us.'=>'Orderlänken är inte giltig. Använd länken i ditt ordermejl, eller kontakta oss.','Status:'=>'Status:','Your downloads are ready. They are available until %s.'=>'Dina nedladdningar är klara. De finns tillgängliga till och med %s.','Your downloads are ready.'=>'Dina nedladdningar är klara.','The download period for this order has ended. Contact us if you need the files again.'=>'Nedladdningsperioden för ordern är slut. Kontakta oss om du behöver filerna igen.','Downloads appear here when the payment has arrived.'=>'Nedladdningarna visas här när betalningen har kommit in.','Your gift cards'=>'Dina presentkort','%s left'=>'%s kvar','Receipt (print or save as PDF)'=>'Kvitto (skriv ut eller spara som PDF)','Invoice (print or save as PDF)'=>'Faktura (skriv ut eller spara som PDF)','Keep the link to this page to yourself: anyone who has it can see the order and download the files.'=>'Behåll länken till den här sidan för dig själv: alla som har den kan se ordern och ladda ner filerna.','Order date'=>'Orderdatum','Paid'=>'Betald','Not paid'=>'Inte betald','Paid with gift card (…%s)'=>'Betalt med presentkort (…%s)','Of which VAT %1$s %% (on %2$s)'=>'Varav moms %1$s %% (på %2$s)','How to pay'=>'Så betalar du','Reference: order %d'=>'Referens: order %d','Print or save as PDF'=>'Skriv ut eller spara som PDF','Link not valid'=>'Länken är inte giltig','Continue as %s. The link works once.'=>'Fortsätt som %s. Länken fungerar en gång.','Sign in and open the gallery'=>'Logga in och öppna galleriet','This sign-in link is not valid'=>'Inloggningslänken är inte giltig','It has expired or has already been used. Ask for a new link on the gallery page, or sign in with your password.'=>'Den har gått ut eller har redan använts. Be om en ny länk på gallerisidan, eller logga in med ditt lösenord.','Go to the login page'=>'Gå till inloggningssidan','Before you view the photos'=>'Innan du ser bilderna','Enter a valid email address to accept the terms.'=>'Ange en giltig e-postadress för att godkänna villkoren.','Your email address'=>'Din e-postadress','I have read and accept these terms'=>'Jag har läst och godkänner villkoren','This browser remembers your acceptance for 30 days. The photographer keeps a record of it with the date and your account or email address. No IP address or browser details are stored.'=>'Webbläsaren kommer ihåg ditt godkännande i 30 dagar. Fotografen sparar en uppgift om det med datum och ditt konto eller din e-postadress. Ingen IP-adress eller uppgift om webbläsaren sparas.','%1$s: %2$s'=>'%1$s: %2$s','Make new web copies of every photo in this gallery from the originals, with the current settings? This can take a while. The originals are not changed.'=>'Göra nya webbkopior av alla bilder i galleriet från originalen, med nuvarande inställningar? Det kan ta en stund. Originalen ändras inte.','Starting…'=>'Startar…','Processing photos: %1$d of %2$d…'=>'Bearbetar bilder: %1$d av %2$d…','New copies made for %1$d photos. %2$d could not be processed and were left unchanged:'=>'Nya kopior gjordes för %1$d bilder. %2$d kunde inte bearbetas och lämnades oförändrade:','New copies made for %d photo. Reload the page to see them.'=>'Nya kopior gjordes för %d bild. Ladda om sidan för att se den.' . "\0" . 'Nya kopior gjordes för %d bilder. Ladda om sidan för att se dem.','Stopped: %s Photos already done keep their new copies; the rest are unchanged.'=>'Stoppad: %s Bilder som redan är klara behåller sina nya kopior; resten är oförändrade.','Save the gallery to create its secret link.'=>'Spara galleriet för att skapa den hemliga länken.','Create a new link? The current link stops working, also for everyone who already opened it.'=>'Skapa en ny länk? Den nuvarande länken slutar fungera, även för alla som redan har öppnat den.','Copied'=>'Kopierad','Copy link'=>'Kopiera länken','New link'=>'Ny länk','Clients'=>'Kunder','Password protected. Change it under Status → Visibility.'=>'Lösenordsskyddat. Ändra det under Status → Synlighet.','No password. You can add one under Status → Visibility.'=>'Inget lösenord. Du kan lägga till ett under Status → Synlighet.','Visitors give their email address (with consent) before seeing the photos. You find the addresses under SlashPhoto → Visitors. Logged-in visitors are not asked.'=>'Besökarna lämnar sin e-postadress (med samtycke) innan de ser bilderna. Adresserna finns under SlashPhoto → Besökare. Inloggade besökare tillfrågas inte.','Same as parent gallery'=>'Som i överordnat galleri','No'=>'Nej','After this day only you can see the gallery. Leave empty for no end date.'=>'Efter den här dagen kan bara du se galleriet. Lämna tomt för inget slutdatum.','Applies to images uploaded after the change. Originals are never changed.'=>'Gäller bilder som laddas upp efter ändringen. Originalen ändras aldrig.','Optional. Each acceptance is logged with the date and the visitor’s account or email address (SlashPhoto → Visitors).'=>'Valfritt. Varje godkännande loggas med datum och besökarens konto eller e-postadress (SlashPhoto → Besökare).','This is a sub-gallery: the password, client list, secret link, email request, end date and terms of the galleries above it also apply.'=>'Det här är ett undergalleri: lösenord, kundlista, hemlig länk, e-postförfrågan, slutdatum och villkor för gallerierna ovanför gäller också.','Let clients choose favourites'=>'Låt kunderna välja favoriter','Logged-in clients mark images and send their selection to you. Visitors without an account keep favourites in their own browser only.'=>'Inloggade kunder markerar bilder och skickar sitt urval till dig. Besökare utan konto sparar favoriterna bara i sin egen webbläsare.','On, as a separate selection'=>'På, som ett separat urval','Off for this gallery'=>'Av för det här galleriet','Maximum number of images'=>'Högsta antal bilder','0 means no limit. Applies to the whole selection, including sub-galleries.'=>'0 betyder ingen gräns. Gäller hela urvalet, även undergallerier.','Sent selections appear in the “Client selections” box at the bottom of the editor (Meta Boxes). You also get an email.'=>'Skickade urval visas i rutan ”Kundernas urval” längst ner i redigeraren (Metarutor). Du får också ett mejl.','Default (%s)'=>'Standard (%s)','Default (not for sale)'=>'Standard (inte till salu)','Visitors who can see this gallery can buy downloads and prints of its photos at these prices. Sub-galleries use the same list unless they choose another.'=>'Besökare som kan se galleriet kan köpa nedladdningar och prints av bilderna till de här priserna. Undergallerier använder samma lista om de inte väljer en annan.','Upload full-size originals, also RAW, HEIC, TIFF and PSD. SnapOtter makes the display copies; originals are kept private.'=>'Ladda upp original i full storlek, även RAW, HEIC, TIFF och PSD. SnapOtter gör visningskopiorna; originalen hålls privata.','Upload full-size originals (JPEG, PNG, WebP, AVIF). Display copies are made automatically; originals are kept private.'=>'Ladda upp original i full storlek (JPEG, PNG, WebP, AVIF). Visningskopior görs automatiskt; originalen hålls privata.','Choose files…'=>'Välj filer…','%d image added. It shows on the gallery page.'=>'%d bild har lagts till. Den visas på gallerisidan.' . "\0" . '%d bilder har lagts till. De visas på gallerisidan.','%s: this file type cannot be added.'=>'%s: den här filtypen kan inte läggas till.','Upload failed.'=>'Uppladdningen misslyckades.','Added'=>'Tillagd','Making the display copy…'=>'Gör visningskopian…','Uploading %d%%'=>'Laddar upp %d%%','Waiting'=>'Väntar','This gallery'=>'Det här galleriet','(no title)'=>'(ingen titel)','Passwords, client lists, expiry dates and terms of the gallery always apply.'=>'Galleriets lösenord, kundlistor, slutdatum och villkor gäller alltid.','SlashPhoto gallery'=>'SlashPhoto-galleri','Choose the gallery to show.'=>'Välj galleriet som ska visas.','block titleSlashPhoto gallery'=>'SlashPhoto-galleri','block descriptionShows a SlashPhoto gallery with its sub-galleries, lightbox and 360° viewer. Access rules of the gallery always apply.'=>'Visar ett SlashPhoto-galleri med undergallerier, bildvisare och 360°-visare. Galleriets åtkomstregler gäller alltid.','block keywordphoto'=>'bild','block keywordgallery'=>'galleri','block keywordpanorama'=>'panorama','block keyword360'=>'360','Search photos'=>'Sök bilder','Search'=>'Sök','Show all'=>'Visa alla','Title, caption, file name, keywords, camera, lens, copyright or date (2025-07-31). Several words must all match.'=>'Titel, bildtext, filnamn, nyckelord, kamera, objektiv, upphovsrätt eller datum (2025-07-31). Flera ord måste alla matcha.','Photos matching “%3$s”: %1$d of %2$d.'=>'Bilder som matchar ”%3$s”: %1$d av %2$d.','Licence: %s'=>'Licens: %s','Import folder'=>'Importmapp','Quality'=>'Kvalitet','File type'=>'Filtyp','JPEG (works everywhere)'=>'JPEG (fungerar överallt)','WebP (smaller files)'=>'WebP (mindre filer)','AVIF (smallest files)'=>'AVIF (minsta filerna)','not supported by this server'=>'stöds inte av den här servern','For the display copy and all sizes of JPEG uploads. All current browsers show WebP and AVIF. Originals and downloads keep their own format. Applies to new uploads; use Make new copies for earlier photos.'=>'För visningskopian och alla storlekar av JPEG-uppladdningar. Alla aktuella webbläsare visar WebP och AVIF. Original och nedladdningar behåller sitt eget format. Gäller nya uppladdningar; använd Gör nya kopior för tidigare bilder.','Copy originals into a folder on the server, with SFTP, FTP, a synced folder or a script, instead of uploading them in the browser. Each sub-folder is a gallery: name it after the gallery’s ID or slug to add photos to it, or give it a new name to create an unpublished gallery with that title. Photos are imported like uploads and removed from the folder; other files are left alone.'=>'Kopiera original till en mapp på servern, med SFTP, FTP, en synkroniserad mapp eller ett skript, i stället för att ladda upp dem i webbläsaren. Varje undermapp är ett galleri: ge den galleriets ID eller slug för att lägga till bilder i det, eller ett nytt namn för att skapa ett opublicerat galleri med den titeln. Bilderna importeras som uppladdningar och tas bort från mappen; andra filer lämnas orörda.','Folder'=>'Mapp','Inside the uploads folder it is protected against web access on Apache and LiteSpeed. To use a folder outside the web root, define SLASHPHOTO_INBOX_DIR in wp-config.php.'=>'Inuti uppladdningsmappen skyddas den mot webbåtkomst på Apache och LiteSpeed. För att använda en mapp utanför webbroten definierar du SLASHPHOTO_INBOX_DIR i wp-config.php.','Automatic import'=>'Automatisk import','Look for new photos every five minutes'=>'Leta efter nya bilder var femte minut','Files changed in the last minute wait for the next run, so copies in progress are not imported half-way. New galleries belong to you. WP-CLI: wp slashphoto inbox.'=>'Filer som ändrats den senaste minuten väntar till nästa körning, så att kopior som pågår inte importeras halvvägs. Nya gallerier tillhör dig. WP-CLI: wp slashphoto inbox.','Last run'=>'Senaste körning','%1$s: %2$d imported, %3$d waiting, %4$d other files left alone.'=>'%1$s: %2$d importerade, %3$d väntar, %4$d andra filer lämnades orörda.','Not imported (moved to the _failed folder):'=>'Inte importerade (flyttade till mappen _failed):','Import now'=>'Importera nu','Every five minutes'=>'Var femte minut','An import is already running.'=>'En import pågår redan.','The import folder cannot be created or written.'=>'Importmappen kan inte skapas eller skrivas till.','The file could not be read.'=>'Filen kunde inte läsas.','Accept the licence terms of the downloads to place the order.'=>'Godkänn licensvillkoren för nedladdningarna för att lägga ordern.','Licences'=>'Licenser','Licence'=>'Licens','Add licence'=>'Lägg till licens','Edit licence'=>'Redigera licens','New licence'=>'Ny licens','Search licences'=>'Sök licenser','No licences found.'=>'Inga licenser hittades.','No licences found in Trash.'=>'Inga licenser hittades i papperskorgen.','Terms customers accept when they buy a download.'=>'Villkor som kunderna godkänner när de köper en nedladdning.','I accept the licence terms for the downloads:'=>'Jag godkänner licensvillkoren för nedladdningarna:','Licence terms'=>'Licensvillkor']];